import{_ as i,I as n,c as s,o as r,j as t,J as l,ah as o,a as d,w as p,ai as c,aj as g}from"./chunks/framework.CDL6_Pj-.js";const x=JSON.parse('{"title":"Data","description":"","frontmatter":{"title":"Data"},"headers":[],"relativePath":"data.md","filePath":"data.md"}'),h={name:"data.md"};function u(m,e,f,T,v,y){const a=n("center");return r(),s("div",null,[e[1]||(e[1]=t("h1",{id:"data",tabindex:"-1"},[d("Data "),t("a",{class:"header-anchor",href:"#data","aria-label":"Permalink to “Data”"},"​")],-1)),l(a,null,{default:p(()=>[...e[0]||(e[0]=[t("img",{src:c,alt:"CMRxRecon2026 Data Overview",width:"90%",style:{"max-width":"600px",height:"auto","margin-bottom":"20px"}},null,-1)])]),_:1}),e[2]||(e[2]=o(`<h2 id="data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to “Data sources”">​</a></h2><p>MRIxFields2026 provides a large-scale multi-field MRI dataset spanning 0.1T to 7T, integrating unpaired multi-center cohorts with prospectively acquired travelling-volunteer paired data.</p><p>💾 <strong>Data Overview: Scale &amp; Diversity</strong></p><ul><li><p><strong>Total Volume:</strong></p><ul><li>Total Volume: The dataset comprises approximately 2500+ retrospective unpaired cases (5 fields; 3 modalities ) and 600 paired cases (40 paired volunteers×5 fields×3 modalities).</li></ul></li><li><p><strong>○Multi-field structural brain MRI data featuring:5 Field Strengths: 0.1T, 1.5T, 3T, 5T, 7T systems.</strong></p><ul><li>3 Modalities: 3D T1-Weighted (T1W), 2D/3D T2-Weighted (T2W), 2D/3D T2 FLAIR.(For 2D data, we utilize a pre-trained super-resolution network to reconstruct 3D volumes from 2D inputs.)</li><li>3 Manufacturers: Siemens Healthineers, United Imaging Healthcare, Point Imaging.</li></ul></li></ul><table tabindex="0"><thead><tr><th>Field Strength</th><th style="text-align:right;">Prospective T1w (paired)</th><th style="text-align:right;">Prospective T2w (paired)</th><th style="text-align:right;">Prospective T2 FLAIR (paired)</th><th style="text-align:right;">Retrospective T1w (unpaired)</th><th style="text-align:right;">Retrospective T2w (unpaired)</th><th style="text-align:right;">Retrospective T2 FLAIR (unpaired)</th><th>Scanners</th><th>Manufacturer</th></tr></thead><tbody><tr><td>0.1T</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (2D)</td><td style="text-align:right;">100 (3D)</td><td style="text-align:right;">100 (3D)</td><td style="text-align:right;">99 (2D)</td><td>piMR-820H</td><td>Point Imaging</td></tr><tr><td>1.5T</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (2D)</td><td style="text-align:right;">104 (3D)</td><td style="text-align:right;">221 (2D)</td><td style="text-align:right;">221 (2D)</td><td>uMR 670</td><td>United Imaging Healthcare</td></tr><tr><td>3T</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (2D)</td><td style="text-align:right;">143 (3D)</td><td style="text-align:right;">142 (3D)</td><td style="text-align:right;">143 (2D)</td><td>MAGNETOM Prisma</td><td>Siemens Healthineers</td></tr><tr><td>5T</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (2D)</td><td style="text-align:right;">121 (3D)</td><td style="text-align:right;">43 (3D)</td><td style="text-align:right;">102 (2D)</td><td>uMR Jupiter</td><td>United Imaging Healthcare</td></tr><tr><td>7T</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (3D)</td><td style="text-align:right;">40 (2D)</td><td style="text-align:right;">235 (3D)</td><td style="text-align:right;">81 (3D)</td><td style="text-align:right;">84 (2D)</td><td>MAGNETOM Terra</td><td>Siemens Healthineers</td></tr></tbody></table><p>📊 <strong>Dataset seperation: Training, Validation, and Testing</strong></p><h3 id="overall-split" tabindex="-1">Overall Split <a class="header-anchor" href="#overall-split" aria-label="Permalink to “Overall Split”">​</a></h3><ul><li>Training set: 1945+ cases (T1W, T2W, T2 FLAIR), consisting of the 1900+ retrospective unpaired cases together with 45 paired cases (3 paired volunteers× 5 fields×3 modalities)</li><li>Validation set: 255 cases, corresponding to 17 volunteers × 5 fields × 3 modalities</li><li>Test set: 300 cases, corresponding to 20 held-out volunteers × 5 fields × 3 modalities</li></ul><p>The precise role of each split varies across tasks, depending on whether the task is driven primarily by unpaired learning, paired target-domain supervision, or controllable conditional generation.</p><h3 id="task-1-ultra-high-field-mri-synthesis-from-arbitrary-input-field-strengths" tabindex="-1">Task 1: Ultra-High-Field MRI Synthesis from Arbitrary Input Field Strengths <a class="header-anchor" href="#task-1-ultra-high-field-mri-synthesis-from-arbitrary-input-field-strengths" aria-label="Permalink to “Task 1: Ultra-High-Field MRI Synthesis from Arbitrary Input Field Strengths”">​</a></h3><ul><li><p><strong>Training Set (1945+ cases)</strong></p><ul><li>The training set consists 1900+ retrospective unpaired cases, supplemented with 45 paired cases (3 paired volunteers× 5 fields×3 modalities).</li></ul></li><li><p><strong>Validation Set (255 cases):</strong></p><ul><li>The validation set consists of 17 travelling volunteers scanned across five field strengths and 3 modalities (17 × 5 × 3 =255 cases).</li></ul><p>These paired data enable controlled within-case validation against corresponding 7T targets.</p></li><li><p><strong>Test Set (300 cases):</strong></p><ul><li>The test set includes 20 held-out travelling volunteers scanned across five field strengths and 3 modalities (20 × 5 × 3 = 300 cases).</li></ul><p>Paired 7T references are withheld and used exclusively for final evaluation.</p></li></ul><h3 id="task-2-higher-field-mri-generation-from-ultra-low-field-mri" tabindex="-1">Task 2: Higher-Field MRI Generation from Ultra-Low-Field MRI <a class="header-anchor" href="#task-2-higher-field-mri-generation-from-ultra-low-field-mri" aria-label="Permalink to “Task 2: Higher-Field MRI Generation from Ultra-Low-Field MRI”">​</a></h3><ul><li><p><strong>Training Set (1945+ cases)</strong></p><ul><li>The training set consists 1900+ retrospective unpaired cases, supplemented with 45 paired cases (3 paired volunteers× 5 fields×3 modalities).</li></ul></li><li><p><strong>Validation Set (255 cases):</strong></p><ul><li>The validation set consists of 17 travelling volunteers (17 × 5 × 3 =255 cases), including paired 0.1T and higher-field scans with 3 modalities for within-case evaluation.</li></ul></li><li><p><strong>Test Set (300 cases):</strong></p><ul><li>The test set consists of 20 held-out travelling volunteers (20 × 5 × 3 = 300 cases).</li></ul><p>The 0.1T images serve as inputs, while higher-field references are withheld for evaluation.</p></li></ul><h3 id="task-3-controllable-field-to-field-mri-synthesis-with-a-unified-conditional-model" tabindex="-1">Task 3: Controllable Field-to-Field MRI Synthesis with a Unified Conditional Model <a class="header-anchor" href="#task-3-controllable-field-to-field-mri-synthesis-with-a-unified-conditional-model" aria-label="Permalink to “Task 3: Controllable Field-to-Field MRI Synthesis with a Unified Conditional Model”">​</a></h3><ul><li><p><strong>Training Set (1945+ cases)</strong></p><ul><li>The training set consists 1900+ retrospective unpaired cases, supplemented with 45 paired cases (3 paired volunteers× 5 fields×3 modalities).</li></ul></li><li><p><strong>Validation Set (255 cases):</strong></p><ul><li>The validation set consists of 17 travelling volunteers (N = 255 cases), enabling evaluation across all possible field-to-field translation directions.</li></ul></li><li><p><strong>Test Set (300 cases):</strong></p><ul><li>The test set consists of 20 held-out travelling volunteers (N = 300 cases).</li></ul></li></ul><p>All target-domain references are withheld and used only for final ranking.</p><h2 id="pre-processing" tabindex="-1">Pre-processing <a class="header-anchor" href="#pre-processing" aria-label="Permalink to “Pre-processing”">​</a></h2><p>To ensure anatomical consistency across field strengths while preserving realistic cross-field variability, we designed a unified yet cohort-specific preprocessing pipeline. The pipeline treats the <strong>prospective travelling-volunteer paired cohort</strong> and the <strong>retrospective unpaired multi-field cohort</strong> differently, reflecting their distinct roles in training and evaluation.</p><h3 id="_1-spatial-registration" tabindex="-1">1. Spatial Registration <a class="header-anchor" href="#_1-spatial-registration" aria-label="Permalink to “1. Spatial Registration”">​</a></h3><h4 id="_1-1-prospective-travelling-volunteer-cohort-paired-data" tabindex="-1">1.1 Prospective Travelling-Volunteer Cohort (Paired Data) <a class="header-anchor" href="#_1-1-prospective-travelling-volunteer-cohort-paired-data" aria-label="Permalink to “1.1 Prospective Travelling-Volunteer Cohort (Paired Data)”">​</a></h4><p>For the paired dataset, we adopted a case-specific, 3T-anchored registration strategy to preserve within-case anatomical correspondence across field strengths while minimizing artificial deformation.</p><h5 id="step-0-intra-case-multi-contrast-alignment" tabindex="-1">Step 0: Intra-case multi-contrast alignment <a class="header-anchor" href="#step-0-intra-case-multi-contrast-alignment" aria-label="Permalink to “Step 0: Intra-case multi-contrast alignment”">​</a></h5><p>For each case, T2W and T2 FLAIR images were first rigidly registered to the corresponding T1W image to ensure within-case cross-contrast alignment.</p><h5 id="step-1-skull-stripping" tabindex="-1">Step 1: Skull stripping <a class="header-anchor" href="#step-1-skull-stripping" aria-label="Permalink to “Step 1: Skull stripping”">​</a></h5><p>Skull stripping was then performed using HD-BET on the T1W images, and the resulting brain masks were propagated to T2W and T2 FLAIR images.</p><h5 id="step-2-reference-definition" tabindex="-1">Step 2: Reference definition <a class="header-anchor" href="#step-2-reference-definition" aria-label="Permalink to “Step 2: Reference definition”">​</a></h5><p>The skull-stripped 3T T1W image was rigidly registered to the MNI152 (0.5 mm, skull-off) template, establishing a case-specific reference in standard space.</p><h5 id="step-3-cross-field-alignment" tabindex="-1">Step 3: Cross-field alignment <a class="header-anchor" href="#step-3-cross-field-alignment" aria-label="Permalink to “Step 3: Cross-field alignment”">​</a></h5><p>T1W images from all other field strengths (0.1T, 1.5T, 5T, and 7T) were rigidly registered to the case-specific 3T T1W image in MNI space, ensuring consistent global alignment across fields.</p><h5 id="step-4-nonlinear-refinement-optional" tabindex="-1">Step 4: Nonlinear refinement (optional) <a class="header-anchor" href="#step-4-nonlinear-refinement-optional" aria-label="Permalink to “Step 4: Nonlinear refinement (optional)”">​</a></h5><p>For cases with residual misalignment, SyN nonlinear registration (ANTs) was applied as a refinement step to improve local anatomical correspondence.</p><h5 id="multi-contrast-propagation" tabindex="-1">Multi-contrast propagation <a class="header-anchor" href="#multi-contrast-propagation" aria-label="Permalink to “Multi-contrast propagation”">​</a></h5><p>The estimated transformations from T1W images were propagated to the corresponding T2W and T2 FLAIR images. When necessary, additional SyN-based refinement was applied to these modalities to correct residual mismatch.</p><h4 id="_1-2-retrospective-multi-field-cohort-unpaired-data" tabindex="-1">1.2 Retrospective Multi-Field Cohort (Unpaired Data) <a class="header-anchor" href="#_1-2-retrospective-multi-field-cohort-unpaired-data" aria-label="Permalink to “1.2 Retrospective Multi-Field Cohort (Unpaired Data)”">​</a></h4><p>For the retrospective dataset, <strong>0.1T images</strong> were first skull-stripped using <strong>HD-BET</strong>, after which all modalities were registered to the <strong>MNI152 template (0.5 mm, skull-off)</strong>.</p><h3 id="_2-bias-field-correction-and-intensity-normalization" tabindex="-1">2. Bias Field Correction and Intensity Normalization <a class="header-anchor" href="#_2-bias-field-correction-and-intensity-normalization" aria-label="Permalink to “2. Bias Field Correction and Intensity Normalization”">​</a></h3><p>After spatial registration, <strong>N4 bias field correction</strong> was applied to mitigate intensity inhomogeneity.</p><p>All images were then normalized to the range of <strong>(0, 1)</strong> using <strong>min-max scaling</strong>.</p><h3 id="_3-2d-to-3d-super-resolution-reconstruction" tabindex="-1">3. 2D-to-3D Super-Resolution Reconstruction <a class="header-anchor" href="#_3-2d-to-3d-super-resolution-reconstruction" aria-label="Permalink to “3. 2D-to-3D Super-Resolution Reconstruction”">​</a></h3><p>For acquisitions with inherently anisotropic resolution (i.e., <strong>2D scans</strong>), we employed a learning-based super-resolution strategy to reconstruct volumetric 3D data. Specifically, a pre-trained super-resolution network was used to perform slice-to-volume reconstruction, transforming 2D inputs into isotropic 3D volumes. This approach enables recovery of through-plane structural information and improves cross-plane consistency, which is critical for subsequent cross-field analysis and synthesis tasks.</p><h3 id="_4-quality-control" tabindex="-1">4. Quality Control <a class="header-anchor" href="#_4-quality-control" aria-label="Permalink to “4. Quality Control”">​</a></h3><p>All data underwent <strong>expert-guided quality control</strong>, including:</p><ul><li>Removal of scans with severe motion artifacts</li><li>Exclusion of images with incomplete brain coverage</li><li>Verification of registration accuracy across field strengths and modalities</li></ul><p>This process ensures high data quality and reliable anatomical alignment across the dataset.</p><h3 id="_5-data-organization" tabindex="-1">5. Data Organization <a class="header-anchor" href="#_5-data-organization" aria-label="Permalink to “5. Data Organization”">​</a></h3><p>All processed data are organized according to the <strong>BIDS (Brain Imaging Data Structure)</strong> standard, with consistent metadata across volunteers, field strengths, and acquisition sites.</p><h4 id="reference-information" tabindex="-1">Reference Information <a class="header-anchor" href="#reference-information" aria-label="Permalink to “Reference Information”">​</a></h4><ul><li><strong>ANTs registration</strong>: <a href="https://github.com/antsx/ants" target="_blank" rel="noreferrer">GitHub</a></li><li><strong>Super-resolution</strong>: <a href="https://github.com/csguoh/MambaIR" target="_blank" rel="noreferrer">GitHub</a></li><li><strong>HD-BET</strong>: <a href="https://github.com/BrainLesion/HD-BET" target="_blank" rel="noreferrer">GitHub</a></li></ul><h2 id="post-processing" tabindex="-1">Post-processing <a class="header-anchor" href="#post-processing" aria-label="Permalink to “Post-processing”">​</a></h2><p>To enable anatomically informed downstream analysis, we incorporated a post-processing step based on automated brain segmentation.</p><h3 id="_1-automated-segmentation" tabindex="-1">1. Automated Segmentation <a class="header-anchor" href="#_1-automated-segmentation" aria-label="Permalink to “1. Automated Segmentation”">​</a></h3><p>All processed MRI volumes were segmented using <strong>SynthSeg</strong>, a deep learning-based whole-brain segmentation framework. SynthSeg was selected due to its robustness to variations in image contrast, resolution, and acquisition conditions, making it particularly suitable for multi-field MRI data.</p><p>Segmentation was applied uniformly to all images after preprocessing, without additional manual intervention.</p><h3 id="_2-structural-feature-extraction" tabindex="-1">2. Structural Feature Extraction <a class="header-anchor" href="#_2-structural-feature-extraction" aria-label="Permalink to “2. Structural Feature Extraction”">​</a></h3><p>Based on the segmentation outputs, regional structural measures were derived for each case, including:</p><ul><li>Regional brain volumes for deep gray matter structures</li><li>Bilateral measurements across anatomical regions</li></ul><p>The primary structures include:</p><ul><li>Thalamus</li><li>Caudate</li><li>Putamen</li><li>Pallidum</li><li>Hippocampus</li><li>Amygdala</li><li>Accumbens</li></ul><p>These regions are consistently identifiable across field strengths and are suitable for downstream quantitative analysis.</p><h3 id="_3-quality-control-of-segmentation" tabindex="-1">3. Quality Control of Segmentation <a class="header-anchor" href="#_3-quality-control-of-segmentation" aria-label="Permalink to “3. Quality Control of Segmentation”">​</a></h3><p>To ensure robustness of the segmentation outputs:</p><ul><li>SynthSeg was applied under a unified configuration across all datasets</li><li>Outputs were visually inspected for gross failures or anatomical inconsistencies</li><li>Cases with severe segmentation artifacts were flagged during the quality control stage</li></ul><h3 id="_4-role-in-the-pipeline" tabindex="-1">4. Role in the Pipeline <a class="header-anchor" href="#_4-role-in-the-pipeline" aria-label="Permalink to “4. Role in the Pipeline”">​</a></h3><p>This post-processing step provides anatomically meaningful representations of the MRI data, enabling:</p><ul><li>Standardized structural characterization across field strengths</li><li>Region-wise quantitative analysis</li><li>Compatibility with downstream evaluation and analysis pipelines</li></ul><h3 id="reference-information-1" tabindex="-1">Reference Information <a class="header-anchor" href="#reference-information-1" aria-label="Permalink to “Reference Information”">​</a></h3><ul><li><strong>SynthSeg</strong>: <a href="https://github.com/BBillot/SynthSeg" target="_blank" rel="noreferrer">GitHub Repository</a></li><li><strong>Paper</strong>: <em>SynthSeg: Segmentation of brain MRI scans of any contrast and resolution without retraining</em></li></ul><hr><h3 id="data-directory-structure" tabindex="-1">Data Directory Structure <a class="header-anchor" href="#data-directory-structure" aria-label="Permalink to “Data Directory Structure”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ChallengeData</span></span>
<span class="line"><span>├── Training_retrospective/          # Training (unpaired, different volunteers)</span></span>
<span class="line"><span>│   ├── T1W/</span></span>
<span class="line"><span>│   │   ├── 0.1T/*.nii.gz</span></span>
<span class="line"><span>│   │   ├── 1.5T/*.nii.gz</span></span>
<span class="line"><span>│   │   ├── 3T/*.nii.gz</span></span>
<span class="line"><span>│   │   ├── 5T/*.nii.gz</span></span>
<span class="line"><span>│   │   └── 7T/*.nii.gz</span></span>
<span class="line"><span>│   ├── T2W/</span></span>
<span class="line"><span>│   │   ├── 0.1T/*.nii.gz</span></span>
<span class="line"><span>│   │   ├── 1.5T/*.nii.gz</span></span>
<span class="line"><span>│   │   ├── 3T/*.nii.gz</span></span>
<span class="line"><span>│   │   ├── 5T/*.nii.gz</span></span>
<span class="line"><span>│   │   └── 7T/*.nii.gz</span></span>
<span class="line"><span>│   └── T2FLAIR/</span></span>
<span class="line"><span>│       ├── 0.1T/*.nii.gz</span></span>
<span class="line"><span>│       ├── 1.5T/*.nii.gz</span></span>
<span class="line"><span>│       ├── 3T/*.nii.gz</span></span>
<span class="line"><span>│       ├── 5T/*.nii.gz</span></span>
<span class="line"><span>│       └── 7T/*.nii.gz</span></span>
<span class="line"><span>├── Training_prospective/            # Training (paired, travelling volunteers)</span></span>
<span class="line"><span>│   ├── T1W/ {0.1T, 1.5T, 3T, 5T, 7T}</span></span>
<span class="line"><span>│   ├── T2W/{...}/</span></span>
<span class="line"><span>│   └── T2FLAIR/{...}/</span></span>
<span class="line"><span>├── Validating_prospective/          # Validation (paired)</span></span>
<span class="line"><span>│   ├── T1W/{0.1T, 1.5T, 3T, 5T, 7T}</span></span>
<span class="line"><span>│   ├── T2W/{...}/</span></span>
<span class="line"><span>│   └── T2FLAIR/{...}/</span></span>
<span class="line"><span>└── Testing_prospective/             # Test (paired)</span></span>
<span class="line"><span>    ├── T1W/{0.1T, 1.5T, 3T, 5T, 7T}</span></span>
<span class="line"><span>    ├── T2W/{...}/</span></span>
<span class="line"><span>    └── T2FLAIR/{...}/</span></span></code></pre></div><p>Our naming convention is: &quot;Type_contrast_fieldStrength_ID.nii.gz&quot;, where Type is either P (prospective) or R (retrospective). For example, P_T1W_0.1T_0006.nii.gz. The same ID corresponds to the same volunteer.</p><p>Retrospective data uses global sequential IDs from 0001 to 1056. Each field strength occupies a distinct ID range: 0.1T corresponds to 0001–0100 (100 volunteers), 1.5T to 0101–0328 (228 volunteers), 3T to 0329–0471 (143 volunteers), 5T to 0472–0737 (266 volunteers), and 7T to 0738–1056 (319 volunteers). Since each volunteer was scanned at only one field strength, data across different field strengths are unpaired.</p><p>Prospective data uses IDs from 0001 to 0040. The same ID across all field strengths corresponds to the same volunteer. For example, P_T1W_0.1T_0006.nii.gz and P_T1W_7T_0006.nii.gz are from the same person scanned at 0.1T and 7T respectively. This enables paired training and evaluation across field strengths.</p><p>For retrospective data (from different volunteers), we only performed rigid registration. If you are not satisfied with the cross-contrast alignment, you may perform your own registration. For prospective data (from the same volunteer), we applied deformable registration to achieve better spatial alignment across field strengths and contrasts. However, some degree of mismatch is unavoidable. If you identify any severe misalignment issues in the data, please contact us at: <a href="mailto:mrixfields@outlook.com" target="_blank" rel="noreferrer">mrixfields@outlook.com</a>.</p><hr><div style="margin:24px 0;"><img src="`+g+'" alt="Consortium logos" style="display:block;max-width:60%;height:auto;margin:0 auto;"></div>',76))])}const w=i(h,[["render",u]]);export{x as __pageData,w as default};
